//! Port of `pocketmine\world\generator\noise\Simplex`, `Noise::noise2D()` and `Noise::getFastNoise3D()`.
//!
//! Every floating point expression is evaluated in the same order as the PHP implementation, so the results are
//! bit-for-bit identical. Do not "simplify" the arithmetic here: any change in rounding moves terrain and creates
//! seams against chunks generated by the PHP code path.

const SQRT3: f64 = 1.732_050_807_568_877_2;
const F2: f64 = 0.5 * (SQRT3 - 1.0);
const G2: f64 = (3.0 - SQRT3) / 6.0;
const G22: f64 = G2 * 2.0 - 1.0;
const F3: f64 = 1.0 / 3.0;
const G3: f64 = 1.0 / 6.0;

const GRAD3: [[f64; 3]; 12] = [
    [1.0, 1.0, 0.0], [-1.0, 1.0, 0.0], [1.0, -1.0, 0.0], [-1.0, -1.0, 0.0],
    [1.0, 0.0, 1.0], [-1.0, 0.0, 1.0], [1.0, 0.0, -1.0], [-1.0, 0.0, -1.0],
    [0.0, 1.0, 1.0], [0.0, -1.0, 1.0], [0.0, 1.0, -1.0], [0.0, -1.0, -1.0],
];

const MAX_OCTAVES: i64 = 32;
/// Upper bound on the magnitude of any noise-space coordinate. Below this, every float->int cast and integer
/// operation done by the PHP code is exact and in range, so we never have to emulate PHP's overflow behaviour.
const MAX_COORDINATE: f64 = (1u64 << 48) as f64;
const MAX_GRID_CELLS: usize = 1 << 24;

pub struct Simplex {
    perm: [u8; 512],
    offset_x: f64,
    offset_y: f64,
    offset_z: f64,
    octaves: u32,
    persistence: f64,
    expansion: f64,
}

/// Result of [`Simplex::fast_noise_3d`], indexed `[x][z][y]` like the PHP array.
pub struct NoiseGrid {
    x_size: usize,
    y_size: usize,
    z_size: usize,
    x_rate: usize,
    y_rate: usize,
    z_rate: usize,
    values: Vec<f64>,
}

impl NoiseGrid {
    pub fn x_len(&self) -> usize {
        self.x_size + 1
    }

    pub fn y_len(&self) -> usize {
        self.y_size + 1
    }

    pub fn z_len(&self) -> usize {
        self.z_size + 1
    }

    #[inline]
    fn index(&self, x: usize, z: usize, y: usize) -> usize {
        (x * (self.z_size + 1) + z) * (self.y_size + 1) + y
    }

    #[inline]
    pub fn get(&self, x: usize, z: usize, y: usize) -> f64 {
        self.values[self.index(x, z, y)]
    }

    /// Whether the PHP implementation writes this cell. Cells on the far edges which don't line up with a sample
    /// are left at their initial value (integer 0) by PHP.
    pub fn is_filled(&self, x: usize, z: usize, y: usize) -> bool {
        (x < self.x_size && z < self.z_size && y < self.y_size)
            || (x % self.x_rate == 0 && z % self.z_rate == 0 && y % self.y_rate == 0)
    }
}

impl Simplex {
    /// Returns `None` for any parameters where the PHP implementation would throw or depend on integer overflow
    /// behaviour. Callers are expected to fall back to the PHP implementation in that case.
    pub fn new(
        perm: &[i64],
        offset_x: f64,
        offset_y: f64,
        offset_z: f64,
        octaves: i64,
        persistence: f64,
        expansion: f64,
    ) -> Option<Self> {
        if perm.len() != 512 || !(1..=MAX_OCTAVES).contains(&octaves) {
            return None;
        }
        if ![offset_x, offset_y, offset_z, persistence, expansion].iter().all(|v| v.is_finite()) {
            return None;
        }
        let mut table = [0u8; 512];
        for (slot, &value) in table.iter_mut().zip(perm) {
            *slot = u8::try_from(value).ok()?;
        }

        let result = Self { perm: table, offset_x, offset_y, offset_z, octaves: octaves as u32, persistence, expansion };
        // PHP throws DivisionByZeroError when normalizing by a zero amplitude sum
        let amplitude_sum = result.amplitude_sum();
        if amplitude_sum == 0.0 || !amplitude_sum.is_finite() {
            return None;
        }
        Some(result)
    }

    fn amplitude_sum(&self) -> f64 {
        let mut amp = 1.0;
        let mut max = 0.0;
        for _ in 0..self.octaves {
            max += amp;
            amp *= self.persistence;
        }
        max
    }

    /// Whether noise can be sampled at block coordinates of up to this magnitude without leaving the range where
    /// PHP's integer semantics are trivially reproducible.
    pub fn supports_coordinate(&self, magnitude: f64) -> bool {
        let scaled = magnitude * self.expansion.abs() * (1u64 << (self.octaves - 1)) as f64;
        let offset = self.offset_x.abs().max(self.offset_y.abs()).max(self.offset_z.abs());
        scaled + offset < MAX_COORDINATE
    }

    fn get_noise_3d(&self, x: f64, y: f64, z: f64) -> f64 {
        let x = x + self.offset_x;
        let y = y + self.offset_y;
        let z = z + self.offset_z;

        let s = (x + y + z) * F3;
        // PHP's (int) cast truncates towards zero, same as `as` within range
        let i = (x + s) as i64;
        let j = (y + s) as i64;
        let k = (z + s) as i64;
        let t = (i + j + k) as f64 * G3;
        let x0 = x - (i as f64 - t);
        let y0 = y - (j as f64 - t);
        let z0 = z - (k as f64 - t);

        let (i1, j1, k1, i2, j2, k2): (usize, usize, usize, usize, usize, usize) = if x0 >= y0 {
            if y0 >= z0 {
                (1, 0, 0, 1, 1, 0)
            } else if x0 >= z0 {
                (1, 0, 0, 1, 0, 1)
            } else {
                (0, 0, 1, 1, 0, 1)
            }
        } else if y0 < z0 {
            (0, 0, 1, 0, 1, 1)
        } else if x0 < z0 {
            (0, 1, 0, 0, 1, 1)
        } else {
            (0, 1, 0, 1, 1, 0)
        };

        let x1 = x0 - i1 as f64 + G3;
        let y1 = y0 - j1 as f64 + G3;
        let z1 = z0 - k1 as f64 + G3;
        let x2 = x0 - i2 as f64 + 2.0 * G3;
        let y2 = y0 - j2 as f64 + 2.0 * G3;
        let z2 = z0 - k2 as f64 + 2.0 * G3;
        let x3 = x0 - 1.0 + 3.0 * G3;
        let y3 = y0 - 1.0 + 3.0 * G3;
        let z3 = z0 - 1.0 + 3.0 * G3;

        let ii = (i & 255) as usize;
        let jj = (j & 255) as usize;
        let kk = (k & 255) as usize;

        let perm = &self.perm;
        let gradient = |di: usize, dj: usize, dk: usize| -> &[f64; 3] {
            let inner = perm[kk + dk] as usize;
            let middle = perm[jj + dj + inner] as usize;
            &GRAD3[(perm[ii + di + middle] % 12) as usize]
        };

        let mut n = 0.0;

        let t0 = 0.6 - x0 * x0 - y0 * y0 - z0 * z0;
        if t0 > 0.0 {
            let g = gradient(0, 0, 0);
            n += t0 * t0 * t0 * t0 * (g[0] * x0 + g[1] * y0 + g[2] * z0);
        }

        let t1 = 0.6 - x1 * x1 - y1 * y1 - z1 * z1;
        if t1 > 0.0 {
            let g = gradient(i1, j1, k1);
            n += t1 * t1 * t1 * t1 * (g[0] * x1 + g[1] * y1 + g[2] * z1);
        }

        let t2 = 0.6 - x2 * x2 - y2 * y2 - z2 * z2;
        if t2 > 0.0 {
            let g = gradient(i2, j2, k2);
            n += t2 * t2 * t2 * t2 * (g[0] * x2 + g[1] * y2 + g[2] * z2);
        }

        let t3 = 0.6 - x3 * x3 - y3 * y3 - z3 * z3;
        if t3 > 0.0 {
            let g = gradient(1, 1, 1);
            n += t3 * t3 * t3 * t3 * (g[0] * x3 + g[1] * y3 + g[2] * z3);
        }

        32.0 * n
    }

    /// Equivalent of `Noise::noise3D($x, $y, $z, true)`.
    fn noise_3d_normalized(&self, x: f64, y: f64, z: f64) -> f64 {
        let mut result = 0.0;
        let mut amp = 1.0;
        let mut freq = 1.0;
        let mut max = 0.0;

        let x = x * self.expansion;
        let y = y * self.expansion;
        let z = z * self.expansion;

        for _ in 0..self.octaves {
            result += self.get_noise_3d(x * freq, y * freq, z * freq) * amp;
            max += amp;
            freq *= 2.0;
            amp *= self.persistence;
        }

        result / max
    }

    /// Equivalent of `Noise::getFastNoise3D()`.
    #[allow(clippy::too_many_arguments)]
    pub fn fast_noise_3d(
        &self,
        x_size: i64,
        y_size: i64,
        z_size: i64,
        x_rate: i64,
        y_rate: i64,
        z_rate: i64,
        x: i64,
        y: i64,
        z: i64,
    ) -> Option<NoiseGrid> {
        if x_rate <= 0 || y_rate <= 0 || z_rate <= 0 || x_size < 0 || y_size < 0 || z_size < 0 {
            return None;
        }
        if x_size % x_rate != 0 || y_size % y_rate != 0 || z_size % z_rate != 0 {
            return None;
        }
        let mut magnitude: u64 = 0;
        for (start, size) in [(x, x_size), (y, y_size), (z, z_size)] {
            let end = start.checked_add(size)?;
            magnitude = magnitude.max(start.unsigned_abs()).max(end.unsigned_abs());
        }
        if !self.supports_coordinate(magnitude as f64) {
            return None;
        }

        let cells = usize::try_from(x_size + 1)
            .ok()?
            .checked_mul(usize::try_from(z_size + 1).ok()?)?
            .checked_mul(usize::try_from(y_size + 1).ok()?)?;
        if cells > MAX_GRID_CELLS {
            return None;
        }

        let (xs, ys, zs) = (x_size as usize, y_size as usize, z_size as usize);
        let (xr, yr, zr) = (x_rate as usize, y_rate as usize, z_rate as usize);
        let mut grid = NoiseGrid {
            x_size: xs,
            y_size: ys,
            z_size: zs,
            x_rate: xr,
            y_rate: yr,
            z_rate: zr,
            values: vec![0.0; cells],
        };

        for xx in (0..=xs).step_by(xr) {
            for zz in (0..=zs).step_by(zr) {
                for yy in (0..=ys).step_by(yr) {
                    let index = grid.index(xx, zz, yy);
                    grid.values[index] =
                        self.noise_3d_normalized((x + xx as i64) as f64, (y + yy as i64) as f64, (z + zz as i64) as f64);
                }
            }
        }

        let x_lerp_step = 1.0 / xr as f64;
        let y_lerp_step = 1.0 / yr as f64;
        let z_lerp_step = 1.0 / zr as f64;

        for left_x in (0..xs).step_by(xr) {
            let right_x = left_x + xr;

            for left_z in (0..zs).step_by(zr) {
                let right_z = left_z + zr;

                for left_y in (0..ys).step_by(yr) {
                    let right_y = left_y + yr;

                    let c000 = grid.get(left_x, left_z, left_y);
                    let c100 = grid.get(right_x, left_z, left_y);
                    let c001 = grid.get(left_x, left_z, right_y);
                    let c101 = grid.get(right_x, left_z, right_y);
                    let c010 = grid.get(left_x, right_z, left_y);
                    let c110 = grid.get(right_x, right_z, left_y);
                    let c011 = grid.get(left_x, right_z, right_y);
                    let c111 = grid.get(right_x, right_z, right_y);

                    for x_step in 0..xr {
                        let xx = left_x + x_step;
                        let dx2 = x_step as f64 * x_lerp_step;
                        let dx1 = 1.0 - dx2;

                        let x00 = (c000 * dx1) + (c100 * dx2);
                        let x01 = (c001 * dx1) + (c101 * dx2);
                        let x10 = (c010 * dx1) + (c110 * dx2);
                        let x11 = (c011 * dx1) + (c111 * dx2);

                        for z_step in 0..zr {
                            let zz = left_z + z_step;
                            let dz2 = z_step as f64 * z_lerp_step;
                            let dz1 = 1.0 - dz2;

                            let z0 = x00 * dz1 + x10 * dz2;
                            let z1 = x01 * dz1 + x11 * dz2;

                            // the first cell of the first row is the corner sample itself
                            let y_start = if x_step == 0 && z_step == 0 { 1 } else { 0 };
                            let base = grid.index(xx, zz, left_y);
                            for y_step in y_start..yr {
                                let dy2 = y_step as f64 * y_lerp_step;
                                let dy1 = 1.0 - dy2;

                                grid.values[base + y_step] = dy1 * z0 + dy2 * z1;
                            }
                        }
                    }
                }
            }
        }

        Some(grid)
    }
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;

    /// Deterministic stand-in for the permutation table PHP builds from its RNG.
    pub(crate) fn test_simplex(octaves: i64, persistence: f64, expansion: f64) -> Simplex {
        let mut perm = [0i64; 512];
        for i in 0..256 {
            perm[i] = ((i * 167 + 13) % 256) as i64;
            perm[i + 256] = perm[i];
        }
        Simplex::new(&perm, 12.25, 200.5, 77.125, octaves, persistence, expansion).unwrap()
    }

    #[test]
    fn rejects_parameters_php_cannot_handle_cleanly() {
        let perm = [0i64; 512];
        assert!(Simplex::new(&perm[..511], 0.0, 0.0, 0.0, 4, 0.25, 1.0).is_none());
        assert!(Simplex::new(&perm, 0.0, 0.0, 0.0, 0, 0.25, 1.0).is_none());
        assert!(Simplex::new(&perm, 0.0, 0.0, 0.0, 2, -1.0, 1.0).is_none(), "zero amplitude sum");
        assert!(Simplex::new(&perm, f64::NAN, 0.0, 0.0, 4, 0.25, 1.0).is_none());
        let mut bad = perm;
        bad[3] = 256;
        assert!(Simplex::new(&bad, 0.0, 0.0, 0.0, 4, 0.25, 1.0).is_none());

        let simplex = test_simplex(4, 0.25, 1.0 / 32.0);
        assert!(simplex.fast_noise_3d(16, 16, 16, 4, 8, 3, 0, 0, 0).is_none(), "size not divisible by rate");
        assert!(simplex.fast_noise_3d(16, 16, 16, 4, 0, 4, 0, 0, 0).is_none());
        assert!(simplex.fast_noise_3d(16, 16, 16, 4, 8, 4, i64::MAX - 4, 0, 0).is_none());
        assert!(simplex.fast_noise_3d(16, 16, 16, 4, 8, 4, 1 << 60, 0, 0).is_none());
    }

    #[test]
    fn noise_is_bounded_and_not_constant() {
        let simplex = test_simplex(4, 0.25, 1.0 / 32.0);
        let grid = simplex.fast_noise_3d(16, 64, 16, 4, 8, 4, -160, 0, 320).unwrap();
        let (mut min, mut max) = (f64::MAX, f64::MIN);
        for x in 0..16 {
            for z in 0..16 {
                for y in 0..64 {
                    let v = grid.get(x, z, y);
                    assert!(v.abs() <= 1.0, "{v} out of range");
                    min = min.min(v);
                    max = max.max(v);
                }
            }
        }
        assert!(max - min > 0.1);
    }

    #[test]
    fn interpolation_matches_trilinear_lerp_between_samples() {
        let simplex = test_simplex(4, 0.25, 1.0 / 32.0);
        let grid = simplex.fast_noise_3d(16, 32, 16, 4, 8, 4, 48, -16, -64).unwrap();
        for x in 0..16 {
            for z in 0..16 {
                for y in 0..32 {
                    let (lx, lz, ly) = (x / 4 * 4, z / 4 * 4, y / 8 * 8);
                    let (fx, fz, fy) = ((x - lx) as f64 / 4.0, (z - lz) as f64 / 4.0, (y - ly) as f64 / 8.0);
                    let mut expected = 0.0;
                    for (cx, wx) in [(lx, 1.0 - fx), (lx + 4, fx)] {
                        for (cz, wz) in [(lz, 1.0 - fz), (lz + 4, fz)] {
                            for (cy, wy) in [(ly, 1.0 - fy), (ly + 8, fy)] {
                                expected += grid.get(cx, cz, cy) * wx * wz * wy;
                            }
                        }
                    }
                    assert!((grid.get(x, z, y) - expected).abs() < 1e-12);
                }
            }
        }
    }

    #[test]
    fn unsampled_far_edge_cells_are_reported_as_unfilled() {
        let simplex = test_simplex(4, 0.25, 1.0 / 32.0);
        let grid = simplex.fast_noise_3d(16, 16, 16, 4, 8, 4, 0, 0, 0).unwrap();
        assert!(grid.is_filled(16, 16, 16));
        assert!(grid.is_filled(15, 15, 15));
        assert!(!grid.is_filled(16, 3, 0));
        assert!(!grid.is_filled(3, 3, 16));
        assert_eq!(grid.get(3, 3, 16), 0.0);
    }
}
